      "harvest": "风调雨顺，五谷丰登，农事兴旺，仓廪充实民生富足。",
      "offspring": "添丁有望，麒麟送子，母子平安，家族香火绵延昌盛。",
      "relocation": "新居大吉，地灵人杰，迁后事业顺遂，家宅安宁繁荣。",
      "lost_property": "物归原主，或得补偿，意外惊喜弥补损失，心安无忧。",
      "travel": "行程顺遂，逢凶化吉，所求皆得，宜远行拓展机遇。",
      "household": "祥云绕宅，福禄双全，家运昌隆，子孙贤孝安居乐业。",
